// src/content.config.ts
import { defineCollection } from 'astro:content';
import { glob, file } from 'astro/loaders';
import { z } from 'astro/zod';

const pages = defineCollection({
  loader: glob({ pattern: '**/*.{md,mdx}', base: './src/content/pages' }),
  schema: ({ image }) => z.object({
    title: z.string(),
    description: z.string().optional(),
    cover: image().optional(),
    coverAlt: z.string().optional(),
  }),
});
const faq = defineCollection({
  loader: file('src/content/faq.json'),
  schema: z.object({ id: z.string(), question: z.string(), answer: z.string() }),
});
const portfolio = defineCollection({
  loader: glob({ pattern: '**/*.md', base: './src/content/portfolio' }),
  schema: ({ image }) => z.object({ title: z.string(), date: z.coerce.date().optional(), cover: image(), coverAlt: z.string(), tags: z.array(z.string()).default([]) }),
});
export const collections = { pages, faq, portfolio };

