      authToken: process.env.SENTRY_AUTH_TOKEN,
    }),
  ],
});
```

Put the DSN and options in sentry.client.config.js at the project root: `Sentry.init({ dsn: import.meta.env.PUBLIC_SENTRY_DSN, integrations: [Sentry.browserTracingIntegration(), Sentry.replayIntegration()], tracesSampleRate: 1.0, replaysSessionSampleRate: 0.1, replaysOnErrorSampleRate: 1.0, enableLogs: true })`. The site is static (no adapter), so no server config is needed.

