// ===== sentry.client.config.ts (project root) =====
import * as Sentry from "@sentry/astro";

Sentry.init({
  dsn: "https://a6f102c315ccfd60751c700250caf376@o4506578567364608.ingest.us.sentry.io/4512239912288256",
  environment: import.meta.env.MODE, // "production" for builds, "development" for astro dev
  // release: injected automatically by the Sentry Vite plugin (GITHUB_SHA in Actions)

  integrations: [
    Sentry.browserTracingIntegration(),
    // Public marketing site: unmask text/media so replays are useful; form inputs stay masked (maskAllInputs default true)
    Sentry.replayIntegration({ maskAllText: false, blockAllMedia: false }),
    // Logs: v11 has no enableLogs flag; this forwards console.warn/error as Sentry Logs
    Sentry.consoleLoggingIntegration({ levels: ["warn", "error"] }),
  ],

  // Tracing (low-traffic site; lower if quota becomes an issue)
  tracesSampleRate: 1.0,

  // Session Replay (Sentry's table: under 10k sessions/day -> 0.25)
  replaysSessionSampleRate: import.meta.env.PROD ? 0.25 : 1.0,
  replaysOnErrorSampleRate: 1.0,

  // v11 collects user info/IP by default; turn off for LGPD on a public site
  dataCollection: { userInfo: false },

  // Metrics: always on in v11 (no enableMetrics). Use Sentry.metrics.count/gauge/distribution.
  // debug: true, // temporarily, while verifying
});

