import { defineConfig } from "astro/config";
import react from "@astrojs/react";
import sitemap from "@astrojs/sitemap";
import partytown from "@astrojs/partytown";
import sentry from "@sentry/astro";

export default defineConfig({
  site: "https://fablabjoinville.github.io", // or the custom domain once CNAME is set
  integrations: [
    react(),
    sitemap({ filter: (page) => !page.includes("/sentry-test") }),
    partytown(),
    sentry({
      org: "projetoresgate-thinktank",
      project: "fablabjoinville-website",
      authToken: process.env.SENTRY_AUTH_TOKEN,
      enabled: { client: true, server: false }, // static output: no runtime server
      sourcemaps: {
        // default globs target dist/**/client/** and miss static dist/_astro/*.map
        filesToDeleteAfterUpload: ["./dist/**/*.map"],
        // optional: skip map generation/upload on local builds without a token
        // disable: !process.env.SENTRY_AUTH_TOKEN,
      },
      telemetry: false, // optional: bundler-plugin telemetry
    }),
  ],
});
// v11 build options (BuildTimeOptionsBase + SdkInitPaths + autoInstrumentation + enabled):
// org, project, authToken, sentryUrl, release{name,...}, sourcemaps{assets,disable,filesToDeleteAfterUpload},
// bundleSizeOptimizations, telemetry, silent, debug, errorHandler, clientInitPath, serverInitPath.
// REMOVED in v11: sourceMapsUploadOptions, unstable_sentryVitePluginOptions (they only print a warning). Runtime options like dsn or replays*SampleRate
// belong in sentry.client.config, not in the integration.

