// ===== src/components/IslandBoundary.tsx (React island error boundary) =====
import * as Sentry from "@sentry/react"; // same exact version as @sentry/astro; never call Sentry.init here
import type { ComponentType } from "react";

export function withIslandBoundary<P extends object>(Component: ComponentType<P>, island: string) {
  return Sentry.withErrorBoundary(Component, {
    fallback: ({ resetError }) => (
      <div role="alert">
        <p>Algo deu errado.</p>
        <button type="button" onClick={resetError}>Tentar novamente</button>
      </div>
    ),
    beforeCapture: (scope) => scope.setTag("island", island),
  });
}
